<template>
  <div id="main">
    <main-carousel></main-carousel>
    <div class="button-wrap">
      <div
        class="button"
        :style="buttonStyles.button1"
        @mouseover="changedColor('button1')"
        @mouseout="originalColor('button1')"
      >
        <button class="game-button" @click="$router.push('/beginner')">
          Info
        </button>
        <div class="discription">사용 설명서</div>
      </div>

      <div
        class="button"
        :style="buttonStyles.button2"
        @mouseover="changedColor('button2')"
        @mouseout="originalColor('button2')"
      >
        <button class="game-button" @click="$router.push('/intermediate')">
          Elementary school Lion
        </button>
        <div class="discription">블록체인이 처음인 아기 사자는 여기로!</div>
      </div>

      <div
        class="button"
        :style="buttonStyles.button3"
        @mouseover="changedColor('button3')"
        @mouseout="originalColor('button3')"
      >
        <button class="game-button" @click="$router.push('/advanced')">
          Middle shcool Lion
        </button>
        <div class="discription">똑똑이 사자는 이쪽으로!</div>
      </div>
      <div
        class="button"
        :style="buttonStyles.button4"
        @mouseover="changedColor('button4')"
        @mouseout="originalColor('button4')"
      >
        <button class="game-button" @click="$router.push('/point')">
          Events
        </button>
        <div class="discription">이벤트 참여</div>
      </div>
    </div>
  </div>
</template>
<script>
import { RouterView } from "vue-router";
import carousel from "./carousel.vue";

export default {
  components: {
    "main-carousel": carousel,
    RouterView
  },
  data() {
    return {
      buttonStyles: {
        button1: { backgroundColor: "#e5e3c8" },
        button2: { backgroundColor: "#e5e3c8" },
        button3: { backgroundColor: "#e5e3c8" },
        button4: { backgroundColor: "#e5e3c8" }
      }
    };
  },
  methods: {
    changedColor(buttonKey) {
      this.buttonStyles[buttonKey].backgroundColor = "#d9d6af";
    },
    originalColor(buttonKey) {
      this.buttonStyles[buttonKey].backgroundColor = "#e5e3c8";
    }
  }
};
</script>

<style scoped>
@import url("https://fonts.googleapis.com/css2?family=Caprasimo&family=Gaegu&family=Jua&family=Yanone+Kaffeesatz:wght@700&display=swap");

#main {
  background-color: #f0f6e2;
  margin-bottom: 2vh;
}
.button-wrap {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr 1fr;
  justify-content: space-between;
  gap: 20px;
  padding: 40px;
  list-style-type: none;
  background-color: #e5e3c8;
  text-align: center;
  border-radius: 5px;
  margin-left: 5vw;
  margin-right: 5vw;
}
.game-button {
  height: 12vh;
  max-width: 800vw;
  font-size: 2rem;
  color: #392504;
  border-color: rgba(0, 0, 0, 0);
  background-color: rgba(0, 0, 0, 0);
  font-family: "Caprasimo", cursive;
  word-wrap: break-word;
  border-radius: 5px;
}

.button {
  border: 2px solid #302e16;
  border-radius: 15px;
  word-wrap: break-word;
  padding: 1rem;
  transition: border-radius 0.3s ease;
}

.discription {
  word-break: keep-all;
  align-items: center;
  font-family: "Jua", sans-serif;
  font-size: 20px;
  color: #392504;
  margin-bottom: 1rem;
}

@media screen and (max-width: 1024px) {
  .button-wrap {
    grid-template-columns: 1fr 1fr;
    margin-left: 5vw;
    margin-right: 5vw;
    gap: 16px;
  }

  .game-button {
    font-size: 1.5rem;
    height: 10vh;
  }

  .discription {
    font-size: 18px;
  }

  .button1 {
    border-radius: 25px;
  }
}

@media screen and (max-width: 600px) {
  .button-wrap {
    grid-template-columns: 1fr;
    margin-left: 3vw;
    margin-right: 3vw;
    gap: 12px;
  }

  .game-button {
    font-size: 1.2rem;
    height: 9vh;
  }

  .discription {
    font-size: 16px;
  }

  .button1 {
    border-radius: 40px;
  }
}
</style>



